insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$bauru$q$, $q$https://www.emdurb.bauru.sp.gov.br/NET/emdurb/institucional/decretos/Dec%2011096-09.pdf (Decreto 11.096/2009; DO de Bauru nº 1.747, 05/12/2009: https://www2.bauru.sp.gov.br/arquivos/sist_diariooficial/2009/12/do_20091205_1747.pdf)$q$, $q$Ato oficial de Bauru: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM): polígono da Zona A pelos cruzamentos das vias do perímetro e vias do perímetro por nome.$q$, 7, $q$Dec. 11.096/2009, art. 3º, I, c: acesso à Zona A (Central) proibido a veículos com comprimento acima de 13,20 m ou PBT acima de 15 t das 7h às 19h, todos os dias (leitura adotada: o horário vale para a frase inteira; confiança média). Zona A = interior do perímetro R. Antônio Alves, R. Primeiro de Agosto, R. Azarias Leite e R. Cussy Júnior, incluídos os dois lados dessas vias (art. 2º, §1º): zona + regra de via para o perímetro. Carga e descarga nas Zonas A e B (art. 3º, I, a, e II, a) fica desativada (operação).$q$);
